#nullable enable

using Campaigns.Contracts;
using Campaigns.Views;
using Marten;
using Shouldly;
using Xunit;

namespace Campaigns.IntegrationTests.Slices.Campaigns;

/// <summary>
/// Generated from the model's GIVEN/THEN cells, NOT from the implementation. Pattern: view. Status: ready.
/// Owned by backend-agent. No WHEN: a read model only reads events that already exist.
///
/// WHAT THESE GTs ARE FOR: <c>identity="messageId, recipient"</c> says a row is the PAIRING, and until these
/// three existed nothing checked it. The model states the grain; only a test can hold the code to it.
///
/// A row here is finer-grained than every event feeding it — one MessageQueued, N rows — which is the tell
/// for an <c>EventProjection</c> (recipe 3) and the one shape no <c>Identity&lt;T&gt;</c> can express, since
/// Identity maps an event to exactly one row. But note what the GTs do NOT say: nothing below mentions
/// EventProjection, and nothing below would change if the fan-out were done another way. That separation is
/// deliberate — the model constrains the contract, the implementation chooses the mechanism.
/// </summary>
public sealed class DeliveryLogTests(AppFixture fixture) : IntegrationContext(fixture)
{
    /// <summary>A second fixed Message stream key, so "two messages" can be named rather than invented.</summary>
    private static readonly Guid SecondMessageId = Guid.Parse("77777777-7777-7777-7777-777777777777");

    private Task Queued(Guid messageId, params string[] recipients) =>
        Given(messageId, new MessageQueued(
            messageId, SeedData.CampaignId, QueueMessageTests.SenderId, "January newsletter",
            recipients, SeedData.SeededAt));

    private async Task<List<DeliveryLog>> Rows()
    {
        await using var session = Store.QuerySession();
        var rows = await session.Query<DeliveryLog>().ToListAsync();
        return rows.OrderBy(r => r.Id, StringComparer.Ordinal).ToList();
    }

    // one queued message becomes one row per recipient
    //   GIVEN MessageQueued
    //   THEN  DeliveryLog
    [Fact]
    public async Task OneQueuedMessageBecomesOneRowPerRecipient()
    {
        var messageId = SeedData.MessageId;
        string[] recipients = ["a@example.com", "b@example.com", "c@example.com"];
        await Queued(messageId, recipients);

        var rows = await Rows();

        // ONE EVENT, THREE ROWS. The fan-out itself.
        rows.Count.ShouldBe(3);

        // Which rows, in what order: one per recipient, and the id is the pairing rather than either half.
        rows.Select(r => r.Recipient).ShouldBe(recipients);
        rows.Select(r => r.Id)
            .ShouldBe(recipients.Select(r => DeliveryLogProjection.Key(messageId, r)));

        // And with which values. Every row repeats the message-level data, because a row of this view is a
        // recipient of a message and both halves have to be readable from it.
        rows.ShouldAllBe(r => r.MessageId == messageId);
        rows.ShouldAllBe(r => r.CampaignId == SeedData.CampaignId);
        rows.ShouldAllBe(r => r.Subject == "January newsletter");

        // queuedAt comes from the PAYLOAD, not from the event envelope's Timestamp — so it is the business
        // time and survives a backfill. SenderMonthly's month is the other choice, and finding #1 in the
        // folder README is what that one costs.
        rows.ShouldAllBe(r => r.QueuedAt == SeedData.SeededAt);
    }

    // the same recipient on two messages is two rows
    //   GIVEN MessageQueued, MessageQueued
    //   THEN  DeliveryLog
    [Fact]
    public async Task TheSameRecipientOnTwoMessagesIsTwoRows()
    {
        const string shared = "a@example.com";
        var first = SeedData.MessageId;
        var second = SecondMessageId;

        // TWO MESSAGES ARE TWO STREAMS, and one person is on both of them.
        await Queued(first, shared, "b@example.com");
        await Queued(second, shared);

        var rows = await Rows();
        var forShared = rows.Where(r => r.Recipient == shared).ToList();

        // THE ASSERTION THIS GT EXISTS FOR. A projection keyed on recipient alone passes the previous test
        // and collapses here to a single row — the second message silently overwriting the first, with the
        // row count still looking plausible. Nothing else in this model would notice.
        forShared.Count.ShouldBe(2);
        forShared.Select(r => r.MessageId).OrderBy(x => x).ShouldBe(new[] { first, second }.OrderBy(x => x));
        forShared.Select(r => r.Id).Distinct().Count().ShouldBe(2);

        // Three rows in total: (first, a), (first, b), (second, a).
        rows.Count.ShouldBe(3);
    }

    // an outcome does not add a log row
    //   GIVEN MessageQueued, MessageDelivered
    //   THEN  DeliveryLog
    [Fact]
    public async Task AnOutcomeDoesNotAddALogRow()
    {
        var messageId = SeedData.MessageId;
        await Queued(messageId, "a@example.com", "b@example.com");

        // "UNCHANGED" IS A CLAIM ABOUT A DIFFERENCE, so it needs the before. Comparing against a constant
        // would only say "there are still two rows", which a projection that replaced one row with another
        // would satisfy. DeliveryLog is a record, so this compares every field of every row.
        var before = await Rows();
        before.Count.ShouldBe(2);

        await Given(messageId, new MessageDelivered(messageId, "a@example.com", SeedData.SeededAt));

        // AND THE IGNORED EVENT REALLY IS IN THE STORE. Without this the test passes vacuously against a
        // GIVEN that never landed — which is the failure mode of every assertion about what is NOT there.
        (await EventsFor(messageId)).Length.ShouldBe(2);

        var after = await Rows();

        // ONLY MessageQueued FEEDS THIS VIEW. The drawing already says so — one arrow, from one event — and
        // this is the only thing that makes that claim executable. A projection that also reacted to
        // outcomes would double rows, or invent a row for a recipient nobody queued, and every other test
        // in this file would still pass.
        after.ShouldBe(before);
    }
}
